import { Icon } from "@/registry/erbium/ui/icon";

import { ToggleGroup, ToggleGroupItem } from "@/registry/erbium/ui/toggle-group";

export const ToggleGroupVertical = () => (
  <ToggleGroup multiple orientation="vertical" spacing={1} defaultValue={["bold", "italic"]}>
    <ToggleGroupItem value="bold" aria-label="Toggle bold">
      <Icon name="bold" />
    </ToggleGroupItem>
    <ToggleGroupItem value="italic" aria-label="Toggle italic">
      <Icon name="italic" />
    </ToggleGroupItem>
    <ToggleGroupItem value="underline" aria-label="Toggle underline">
      <Icon name="underline" />
    </ToggleGroupItem>
  </ToggleGroup>
);

import { ToggleGroupVertical } from "../examples/toggle-group-vertical";

const Example = () => <ToggleGroupVertical />;

export default Example;
